SELECT id, user_id, name, type, icon, is_preset, status
FROM category
WHERE user_id = #{userId}

    AND type = #{type}

ORDER BY type DESC, id ASC

SELECT id, user_id, name, type, icon, is_preset, status
FROM category
WHERE id = #{id} AND user_id = #{userId}

SELECT id, user_id, name, type, icon, is_preset, status
FROM category
WHERE user_id = #{userId} AND type = #{type} AND name = #{name}
